local resourceName = GetCurrentResourceName()
local scoreboardConfig = Config.FootballScoreboard or {}

local Scoreboard = {
    dui = nil,
    txd = nil,
    txdName = scoreboardConfig.TxdName or "football_scoreboard_txd",
    txnName = scoreboardConfig.TxnName or "football_scoreboard_tex",
    boards = {},
    totalSeconds = math.max(1, (tonumber(scoreboardConfig.DefaultMatchMinutes) or 90) * 60),
    lastMessage = "",
    state = {},
    uiDirty = false,
    pendingGoalPayload = nil,
    goalReceivedAt = 0,
    nativeScreenBind = nil,
    screenOff = true,
    debugUrlMode = nil,
    imageTestMode = false,
    --- json.encode anahtar sirasi degisken; ayni skorboard durumu icin bile farkli string
    --- uretilebiliyor. Gorunumu temsil eden sabit bir parmak izi ile gereksiz SendDuiMessage kesilir.
    lastDuiVisualHash = nil,
}

local function createNamedRenderTargetForModel(modelHash, rtName)
    if not IsNamedRendertargetRegistered(rtName) then
        RegisterNamedRendertarget(rtName, false)
    end
    if not IsNamedRendertargetLinked(modelHash) then
        LinkNamedRendertarget(modelHash)
    end
    if IsNamedRendertargetRegistered(rtName) then
        return GetNamedRendertargetRenderId(rtName)
    end
    return nil
end

local function releaseNamedRenderTarget(rtName)
    if rtName and IsNamedRendertargetRegistered(rtName) then
        ReleaseNamedRendertarget(rtName)
    end
end

local function drawBoardViaRenderTarget(board)
    if not board.entity or not DoesEntityExist(board.entity) then return false end
    if not board.renderTarget or not board.modelHash then return false end

    if not board.rtHandle then
        board.rtHandle = createNamedRenderTargetForModel(board.modelHash, board.renderTarget)
        if board.rtHandle then
            print(("[seoul_soccer] Named Render Target '%s' bound to model 0x%X (handle=%d)"):format(
                board.renderTarget, board.modelHash, board.rtHandle))
        end
    end
    if not board.rtHandle then return false end

    SetTextRenderId(board.rtHandle)
    Set_2dLayer(4)
    SetScriptGfxDrawBehindPausemenu(1)

    DrawRect(0.5, 0.5, 1.0, 1.0, 0, 0, 0, 255)
    DrawSprite(Scoreboard.txdName, Scoreboard.txnName, 0.5, 0.5, 1.0, 1.0, tonumber(board.screenRotation) or 0.0, 255, 255, 255, 255)

    SetTextRenderId(GetDefaultScriptRendertargetRenderId())
    SetScriptGfxDrawBehindPausemenu(0)

    return true
end

local lazyDui = scoreboardConfig.LazyDui ~= false
local goalOverlayMaxAge = math.max(500, tonumber(scoreboardConfig.GoalOverlayMaxAgeMs) or 2800)

local function scoreboardLabel(path, fallback)
    local value = L(path)
    if type(value) ~= "string" or value == path or value == "" then
        return fallback
    end
    return value
end

local cachedLabels = nil
local cachedLabelsLocale = nil

local function scoreboardLabels()
    local currentLocale = (Config and Config.Locale) or "en"
    if cachedLabels and cachedLabelsLocale == currentLocale then
        return cachedLabels
    end
    cachedLabels = {
        locale = currentLocale,
        home = scoreboardLabel("scoreboard.home", "Home"),
        away = scoreboardLabel("scoreboard.away", "Away"),
        waiting = scoreboardLabel("scoreboard.waiting", "Waiting"),
        live = scoreboardLabel("scoreboard.live", "Live"),
        broadcast = scoreboardLabel("scoreboard.broadcast", "Broadcast"),
        liveScore = scoreboardLabel("scoreboard.live_score", "Live Score"),
        goal = scoreboardLabel("scoreboard.goal", "Goal"),
        ownGoal = scoreboardLabel("scoreboard.own_goal", "Own Goal"),
    }
    cachedLabelsLocale = currentLocale
    return cachedLabels
end

local function encodeDuiMessage(action, data)
    return json.encode({
        action = action,
        data = data,
        labels = scoreboardLabels(),
    })
end

-- json.encode Lua tablolarinda anahtar sirasini garanti etmez; "standby" icin her
-- encode farkli string uretebiliyor, lastMessage ile hic eslesmiyor ve yakindayken
-- tryFlushDui dongusu SendDuiMessage spam'ine yol aciyordu (DUI surekli yenileniyor).
local standbyDuiMessageJson = '{"action":"standby"}'

local function duiVisualStateHash()
    local lb = scoreboardLabels()
    local s = Scoreboard.state
    return ("%s\0%s\0%s\0%s\0%s\0%s\0%s\0%s\0%s"):format(
        tostring(lb.locale),
        tostring(s.homeName or ""),
        tostring(s.awayName or ""),
        tostring(s.homeScore or 0),
        tostring(s.awayScore or 0),
        tostring(s.time or ""),
        tostring(s.period or ""),
        tostring(s.status or ""),
        tostring(s.state or "")
    )
end

local function mergeState(data)
    if type(data) ~= "table" then return end
    for key, value in pairs(data) do
        if value ~= nil then
            Scoreboard.state[key] = value
        end
    end
end

local function periodLabel(key, fallback)
    local localized = scoreboardLabel(("scoreboard.periods.%s"):format(key), nil)
    if localized then
        return localized
    end

    local labels = scoreboardConfig.PeriodLabels
    if type(labels) == "table" and labels[key] then
        return tostring(labels[key])
    end
    return fallback
end

local function formatClock(seconds)
    seconds = math.max(0, math.floor(tonumber(seconds) or 0))
    return ("%02d:%02d"):format(math.floor(seconds / 60), seconds % 60)
end

local function resolveMatchClock(data)
    local total = tonumber(data.totalSeconds) or Scoreboard.totalSeconds
    if total <= 0 then
        total = math.max(1, (tonumber(scoreboardConfig.DefaultMatchMinutes) or 90) * 60)
    end

    if data.totalSeconds then
        Scoreboard.totalSeconds = total
    end

    if data.time then
        return tostring(data.time), data.period or Scoreboard.state.period or "LIVE"
    end

    local timeLeft = tonumber(data.timeLeft)
    local elapsed = tonumber(data.elapsedSeconds)

    if timeLeft then
        elapsed = math.max(0, total - math.max(0, timeLeft))
    elseif not elapsed then
        elapsed = 0
    end

    local stateName = tostring(data.state or Scoreboard.state.state or ""):lower()
    local period = data.period
    if not period then
        if stateName == "warmup" then
            period = periodLabel("warmup", "WARMUP")
        elseif stateName == "countdown" then
            period = periodLabel("countdown", "KICK OFF")
        elseif stateName == "paused" then
            period = periodLabel("paused", "PAUSED")
        elseif stateName == "waiting" then
            period = periodLabel("waiting", "LOBBY")
        elseif stateName == "ended" then
            period = periodLabel("ended", "FULL TIME")
        elseif elapsed < (total * 0.5) then
            period = periodLabel("first_half", "FIRST HALF")
        else
            period = periodLabel("second_half", "SECOND HALF")
        end
    end

    return formatClock(elapsed), period
end

local function playerCoordsNearBoards(playerCoords, maxDistance)
    local maxDistSq = maxDistance * maxDistance
    local px, py, pz = playerCoords.x, playerCoords.y, playerCoords.z
    for _, board in ipairs(Scoreboard.boards) do
        local bc = board.coords
        local dx, dy, dz = px - bc.x, py - bc.y, pz - bc.z
        if (dx * dx + dy * dy + dz * dz) <= maxDistSq then
            return true
        end
    end
    return false
end

local function removeNativeScreenBind()
    local bind = Scoreboard.nativeScreenBind
    if not bind then return end
    RemoveReplaceTexture(bind.dict, bind.txn)
    Scoreboard.nativeScreenBind = nil
end

--- TV modelinde hangi ytd/txn denenecek (ilk basarili AddReplaceTexture kullanilir).
local function scoreboardReplaceCandidateList()
    local rep = scoreboardConfig.ScreenTextureReplace
    local fromCfg = type(rep) == "table" and rep.Candidates or nil
    local out = {}

    if type(fromCfg) == "table" then
        for _, c in ipairs(fromCfg) do
            if type(c) == "table" and c.dict and c.txn then
                out[#out + 1] = { dict = tostring(c.dict), txn = tostring(c.txn) }
            end
        end
    end

    return out
end

--- Crash / yanlis sira sonrasi TV'de beyaz kalmamasi icin tum olasi replace slotlarini temizle.
local function stripScoreboardReplaceTextures()
    removeNativeScreenBind()
    local seen = {}
    for _, pair in ipairs(scoreboardReplaceCandidateList()) do
        if pair.dict and pair.txn then
            local key = pair.dict .. "|" .. pair.txn
            if not seen[key] then
                seen[key] = true
                RemoveReplaceTexture(pair.dict, pair.txn)
            end
        end
    end
end

local function boardUsesHugeDisplayModel(board)
    if board.renderTarget then return false end
    local m = board.model
    if m == false or m == nil then return false end
    local name = type(m) == "string" and m:lower() or ""
    return name:find("huge_display", 1, true) ~= nil
end

local function anyBoardUsesHugeDisplay()
    for _, board in ipairs(Scoreboard.boards) do
        if boardUsesHugeDisplayModel(board) then
            return true
        end
    end
    return false
end

local function tryBindNativeScreenTexture()
    removeNativeScreenBind()
    local rep = scoreboardConfig.ScreenTextureReplace
    if type(rep) ~= "table" or rep.Enabled == false then return end
    if not anyBoardUsesHugeDisplay() then return end

    for _, pair in ipairs(scoreboardReplaceCandidateList()) do
        local dict, txn = pair.dict, pair.txn
        if dict and txn then
            if dict ~= "script_rt" then
                RequestStreamedTextureDict(dict, false)
                local deadline = GetGameTimer() + 2800
                while not HasStreamedTextureDictLoaded(dict) and GetGameTimer() < deadline do
                    Wait(10)
                end
            end
            if AddReplaceTexture(dict, txn, Scoreboard.txdName, Scoreboard.txnName) then
                Scoreboard.nativeScreenBind = { dict = dict, txn = txn }
                return
            end
        end
    end
end

local function buildDuiUrl(page)
    local explicitUrl = scoreboardConfig.DuiUrl
    if type(explicitUrl) == "string" and explicitUrl ~= "" then
        return explicitUrl
    end
    return ("nui://%s/%s"):format(resourceName, page)
end

local function ensureDui()
    if Scoreboard.dui then return true end

    local width = tonumber(scoreboardConfig.DuiWidth) or 1920
    local height = tonumber(scoreboardConfig.DuiHeight) or 1080
    local duiPage = tostring(scoreboardConfig.DuiPage or "web/dist/stadium.html")
    local url = buildDuiUrl(duiPage)
    local packedHtml = LoadResourceFile(resourceName, duiPage)
    print(("[seoul_soccer] Stadium DUI resource file %s: %s"):format(duiPage, packedHtml and (#packedHtml .. " bytes") or "NOT FOUND"))

    print(("[seoul_soccer] Creating stadium DUI: %s (%dx%d)"):format(url, width, height))
    Scoreboard.dui = CreateDui(url, width, height)
    if not Scoreboard.dui then
        print("[seoul_soccer] CreateDui failed for stadium scoreboard")
        return false
    end

    local readyBy = GetGameTimer() + 8000
    while not IsDuiAvailable(Scoreboard.dui) and GetGameTimer() < readyBy do
        Wait(50)
    end

    if not IsDuiAvailable(Scoreboard.dui) then
        print("[seoul_soccer] Stadium DUI did not become available")
        DestroyDui(Scoreboard.dui)
        Scoreboard.dui = nil
        return false
    end

    -- Paint the page before binding the DUI handle into a runtime texture. If the
    -- runtime texture is created while CEF is still on its initial blank frame,
    -- DrawSpritePoly can keep drawing a solid white texture.
    local primed = standbyDuiMessageJson
    SendDuiMessage(Scoreboard.dui, primed)
    Scoreboard.lastMessage = primed
    Scoreboard.lastDuiVisualHash = nil
    for _ = 1, 6 do
        Wait(16)
    end

    SendDuiMessage(Scoreboard.dui, primed)
    local paintMs = math.max(900, tonumber(scoreboardConfig.DuiPaintWaitMs) or 1200)
    local paintUntil = GetGameTimer() + paintMs
    while GetGameTimer() < paintUntil do
        Wait(16)
    end

    local handle = GetDuiHandle(Scoreboard.dui)
    if not handle or handle == 0 then
        print("[seoul_soccer] GetDuiHandle failed for stadium scoreboard")
        DestroyDui(Scoreboard.dui)
        Scoreboard.dui = nil
        return false
    end

    Scoreboard.txd = CreateRuntimeTxd(Scoreboard.txdName)
    Scoreboard.texture = CreateRuntimeTextureFromDuiHandle(Scoreboard.txd, Scoreboard.txnName, handle)
    print(("[seoul_soccer] Stadium DUI texture created: txd=%s txn=%s texture=%s"):format(Scoreboard.txdName, Scoreboard.txnName, tostring(Scoreboard.texture)))

    SendDuiMessage(Scoreboard.dui, primed)
    for _ = 1, 4 do
        Wait(16)
    end

    tryBindNativeScreenTexture()
    return true
end

local function sendDuiRaw(message)
    if not Scoreboard.dui then return end
    SendDuiMessage(Scoreboard.dui, message)
end

local function flushDuiFromState()
    if not Scoreboard.dui then return end

    if Scoreboard.screenOff then
        local msg = standbyDuiMessageJson
        if msg ~= Scoreboard.lastMessage then
            Scoreboard.lastMessage = msg
            sendDuiRaw(msg)
        end
        Scoreboard.pendingGoalPayload = nil
        Scoreboard.uiDirty = false
        Scoreboard.lastDuiVisualHash = nil
        return
    end

    if Scoreboard.pendingGoalPayload then
        local age = GetGameTimer() - Scoreboard.goalReceivedAt
        if age <= goalOverlayMaxAge then
            local goalMsg = encodeDuiMessage("goal", Scoreboard.pendingGoalPayload)
            sendDuiRaw(goalMsg)
            Scoreboard.lastMessage = encodeDuiMessage("update", Scoreboard.state)
            Scoreboard.lastDuiVisualHash = nil
        else
            local visHash = duiVisualStateHash()
            if visHash ~= Scoreboard.lastDuiVisualHash then
                local upd = encodeDuiMessage("update", Scoreboard.state)
                Scoreboard.lastMessage = upd
                Scoreboard.lastDuiVisualHash = visHash
                sendDuiRaw(upd)
            end
        end
        Scoreboard.pendingGoalPayload = nil
        Scoreboard.uiDirty = false
        return
    end

    if not Scoreboard.uiDirty then return end

    local visHash = duiVisualStateHash()
    if visHash == Scoreboard.lastDuiVisualHash then
        Scoreboard.uiDirty = false
        return
    end

    local message = encodeDuiMessage("update", Scoreboard.state)
    Scoreboard.lastMessage = message
    Scoreboard.lastDuiVisualHash = visHash
    sendDuiRaw(message)
    Scoreboard.uiDirty = false
end

local function tryFlushDui(playerCoords, drawDistance)
    if lazyDui and not playerCoordsNearBoards(playerCoords, drawDistance) then
        return
    end
    if not ensureDui() then return end
    flushDuiFromState()
end

local function scheduleDuiUpdate(action, goalData)
    if action == "goal" then
        Scoreboard.pendingGoalPayload = goalData
        Scoreboard.goalReceivedAt = GetGameTimer()
        Scoreboard.uiDirty = true
    else
        Scoreboard.uiDirty = true
    end

    if not lazyDui then
        if ensureDui() then
            flushDuiFromState()
        end
        return
    end

    local ped = PlayerPedId()
    local coords = GetEntityCoords(ped)
    local drawDistance = tonumber(scoreboardConfig.DrawDistance) or 130.0
    tryFlushDui(coords, drawDistance)
end

local function applyPayload(payload, action)
    payload = payload or {}

    if action ~= "goal" then
        local st = tostring(payload.state or ""):lower()
        local noLiveMatch = payload.screenOff == true
            or (payload.active == false and st == "idle")
        if noLiveMatch then
            Scoreboard.screenOff = true
            Scoreboard.pendingGoalPayload = nil
            local time, period = resolveMatchClock(payload)
            local normalized = {
                homeName = payload.homeName or payload.team1Name,
                awayName = payload.awayName or payload.team2Name,
                homeScore = tonumber(payload.homeScore or payload.score1) or 0,
                awayScore = tonumber(payload.awayScore or payload.score2) or 0,
                time = time,
                period = period,
                status = payload.status or Scoreboard.state.status or "LIVE",
                state = payload.state or Scoreboard.state.state,
                active = false,
            }
            mergeState(normalized)
            scheduleDuiUpdate("update")
            return
        end
    end

    Scoreboard.screenOff = false

    local time, period = resolveMatchClock(payload)
    local normalized = {
        homeName = payload.homeName or payload.team1Name,
        awayName = payload.awayName or payload.team2Name,
        homeScore = tonumber(payload.homeScore or payload.score1) or 0,
        awayScore = tonumber(payload.awayScore or payload.score2) or 0,
        time = time,
        period = period,
        status = payload.status or Scoreboard.state.status or "LIVE",
        state = payload.state or Scoreboard.state.state,
        active = payload.active ~= false,
    }

    mergeState(normalized)

    if action == "goal" then
        scheduleDuiUpdate("goal", {
            homeName = Scoreboard.state.homeName,
            awayName = Scoreboard.state.awayName,
            homeScore = Scoreboard.state.homeScore,
            awayScore = Scoreboard.state.awayScore,
            time = Scoreboard.state.time,
            period = Scoreboard.state.period,
            status = Scoreboard.state.status,
            scoringTeam = payload.scoringTeam,
            scorerName = payload.scorerName,
            isOwnGoal = payload.isOwnGoal == true,
        })
        return
    end

    scheduleDuiUpdate("update")
end

local function requestModel(model)
    if not model or model == false then return nil end
    local hash = type(model) == "number" and model or joaat(model)
    if not IsModelInCdimage(hash) or not IsModelValid(hash) then return nil end

    RequestModel(hash)
    local deadline = GetGameTimer() + 3000
    while not HasModelLoaded(hash) and GetGameTimer() < deadline do
        Wait(10)
    end

    if not HasModelLoaded(hash) then return nil end
    return hash
end

local function spawnBoardProp(model, coords, heading)
    local hash = requestModel(model)
    if not hash then return nil, nil end

    local entity = CreateObjectNoOffset(hash, coords.x, coords.y, coords.z, false, false, false)
    if not DoesEntityExist(entity) then return nil, nil end

    SetEntityHeading(entity, tonumber(heading) or 0.0)
    FreezeEntityPosition(entity, true)
    SetEntityCollision(entity, false, false)
    SetEntityInvincible(entity, true)
    SetModelAsNoLongerNeeded(hash)
    return entity, hash
end

local function createBoardObject(board)
    if board.supportModel and board.supportModel ~= false and not board.supportEntity then
        local supportOffset = board.supportOffset or vector3(0.0, 0.0, 0.0)
        local supportCoords = (board.supportCoords or board.coords) + supportOffset
        local supportEntity, supportHash = spawnBoardProp(board.supportModel, supportCoords, board.supportHeading or board.heading)
        board.supportEntity = supportEntity
        board.supportModelHash = supportHash
    end

    if board.entity or not board.model or board.model == false then return end

    local offset = board.modelOffset or vector3(0.0, 0.0, 0.0)
    local coords = board.coords + offset
    local entity, hash = spawnBoardProp(board.model, coords, board.heading)
    board.entity = entity
    board.modelHash = hash
end

local function safeDeleteEntity(entity)
    if entity and DoesEntityExist(entity) then
        SetEntityAsMissionEntity(entity, true, true)
        DeleteEntity(entity)
    end
end

local function deleteBoardObject(board)
    if board.rtHandle then
        releaseNamedRenderTarget(board.renderTarget)
        board.rtHandle = nil
    end
    safeDeleteEntity(board.entity)
    safeDeleteEntity(board.supportEntity)
    board.entity = nil
    board.modelHash = nil
    board.supportEntity = nil
    board.supportModelHash = nil
end

local function cleanupExistingBoardProps()
    local boards = scoreboardConfig.Boards or {}
    local searchRadius = 15.0
    for _, boardCfg in ipairs(boards) do
        if not boardCfg.coords then goto continue end

        if boardCfg.model and boardCfg.model ~= false then
            local hash = GetHashKey(boardCfg.model)
            local offset = boardCfg.modelOffset or vector3(0.0, 0.0, 0.0)
            local pos = boardCfg.coords + offset
            local maxIter = 20
            local obj = GetClosestObjectOfType(pos.x, pos.y, pos.z, searchRadius, hash, false, false, false)
            while obj and obj ~= 0 and DoesEntityExist(obj) and maxIter > 0 do
                safeDeleteEntity(obj)
                maxIter = maxIter - 1
                obj = GetClosestObjectOfType(pos.x, pos.y, pos.z, searchRadius, hash, false, false, false)
            end
        end

        if boardCfg.supportModel and boardCfg.supportModel ~= false then
            local hash = GetHashKey(boardCfg.supportModel)
            local sOffset = boardCfg.supportOffset or vector3(0.0, 0.0, 0.0)
            local pos = (boardCfg.supportCoords or boardCfg.coords) + sOffset
            local maxIter = 20
            local obj = GetClosestObjectOfType(pos.x, pos.y, pos.z, searchRadius, hash, false, false, false)
            while obj and obj ~= 0 and DoesEntityExist(obj) and maxIter > 0 do
                safeDeleteEntity(obj)
                maxIter = maxIter - 1
                obj = GetClosestObjectOfType(pos.x, pos.y, pos.z, searchRadius, hash, false, false, false)
            end
        end

        ::continue::
    end
end

local function basisFromHeading(headingDegrees)
    local heading = math.rad(tonumber(headingDegrees) or 0.0)
    return vector3(math.cos(heading), math.sin(heading), 0.0), vector3(-math.sin(heading), math.cos(heading), 0.0), vector3(0.0, 0.0, 1.0)
end

local function worldFromLocal(origin, headingDegrees, localOffset)
    local right, forward, up = basisFromHeading(headingDegrees)
    return origin + (right * localOffset.x) + (forward * localOffset.y) + (up * localOffset.z)
end

local function entityLocalPoint(entity, localOffset)
    return GetOffsetFromEntityInWorldCoords(entity, localOffset.x, localOffset.y, localOffset.z)
end

local function entityLocalAxis(entity, axis)
    local origin = GetOffsetFromEntityInWorldCoords(entity, 0.0, 0.0, 0.0)
    local point
    if axis == "x" then
        point = GetOffsetFromEntityInWorldCoords(entity, 1.0, 0.0, 0.0)
    elseif axis == "y" then
        point = GetOffsetFromEntityInWorldCoords(entity, 0.0, 1.0, 0.0)
    else
        point = GetOffsetFromEntityInWorldCoords(entity, 0.0, 0.0, 1.0)
    end
    return point - origin
end

local function getModelBoardCorners(board, side)
    if scoreboardConfig.AutoFitModelScreen == false then return nil end
    if not board.entity or not DoesEntityExist(board.entity) or not board.modelHash then return nil end

    local minDim, maxDim = GetModelDimensions(board.modelHash)
    if not minDim or not maxDim then return nil end

    local push = tonumber(board.surfacePush or scoreboardConfig.ModelSurfacePush) or 0.08
    local screenXOffset = tonumber(board.screenXOffset or scoreboardConfig.ModelScreenXOffset) or 0.0
    local screenYOffset = tonumber(board.screenYOffset or scoreboardConfig.ModelScreenYOffset) or 0.0
    local screenDepthOffset = tonumber(board.screenDepthOffset or scoreboardConfig.ModelScreenDepthOffset) or 0.0
    local screenZOffset = tonumber(board.screenZOffset or scoreboardConfig.ModelScreenZOffset) or 0.0
    local useFront = (side or 1.0) >= 0.0
    local screenAxis = tostring(board.screenAxis or scoreboardConfig.ModelScreenAxis or "y"):lower()

    local localCenter
    local widthAxis
    local widthSpan
    if screenAxis == "x" then
        local localX = useFront and (maxDim.x + push + screenDepthOffset) or (minDim.x - push + screenDepthOffset)
        localCenter = vector3(
            localX,
            ((minDim.y + maxDim.y) * 0.5) + screenYOffset,
            ((minDim.z + maxDim.z) * 0.5) + screenZOffset
        )
        widthAxis = entityLocalAxis(board.entity, "y")
        widthSpan = maxDim.y - minDim.y
    else
        local localY = useFront and (maxDim.y + push + screenDepthOffset) or (minDim.y - push + screenDepthOffset)
        localCenter = vector3(
            ((minDim.x + maxDim.x) * 0.5) + screenXOffset,
            localY,
            ((minDim.z + maxDim.z) * 0.5) + screenZOffset
        )
        widthAxis = entityLocalAxis(board.entity, "x")
        widthSpan = maxDim.x - minDim.x
    end

    local center = entityLocalPoint(board.entity, localCenter)
    local width = tonumber(board.screenWidth) or (widthSpan * (tonumber(scoreboardConfig.ModelScreenWidthScale) or 0.62))
    local height = tonumber(board.screenHeight) or ((maxDim.z - minDim.z) * (tonumber(scoreboardConfig.ModelScreenHeightScale) or 0.46))
    local halfWidth = widthAxis * (width * 0.5)
    local halfUp = entityLocalAxis(board.entity, "z") * (height * 0.5)

    return center - halfWidth + halfUp, center + halfWidth + halfUp, center - halfWidth - halfUp, center + halfWidth - halfUp
end

local function getBoardCorners(board, side)
    local mtl, mtr, mbl, mbr = getModelBoardCorners(board, side)
    if mtl then
        return mtl, mtr, mbl, mbr
    end

    if board.model and scoreboardConfig.AutoFitModelScreen ~= false then
        return nil
    end

    local heading = tonumber(board.heading) or 0.0
    local width = tonumber(board.width) or 8.0
    local height = tonumber(board.height) or 4.5
    local surfaceOffset = tonumber(board.surfaceOffset) or 0.04
    side = side or 1.0
    local polyExtra = tonumber(board.polyExtraForward or scoreboardConfig.PolyExtraForward) or 0.12
    local right, forward, up = basisFromHeading(heading)
    local center = board.coords

    if board.supportEntity and DoesEntityExist(board.supportEntity) and board.screenAnchorOffset then
        local anchor = board.screenAnchorOffset
        center = GetOffsetFromEntityInWorldCoords(board.supportEntity, anchor.x, anchor.y, anchor.z)
        heading = GetEntityHeading(board.supportEntity)
        right, forward, up = basisFromHeading(heading)
    end

    center = center + (forward * ((surfaceOffset + polyExtra) * side))

    local halfRight = right * (width * 0.5)
    local halfUp = up * (height * 0.5)

    return center - halfRight + halfUp, center + halfRight + halfUp, center - halfRight - halfUp, center + halfRight - halfUp
end
local function getBoardUv(board)
    local flipX = scoreboardConfig.FlipX
    if board and board.flipX ~= nil then
        flipX = board.flipX
    end

    if flipX == false then
        return 0.0, 1.0
    end
    return 1.0, 0.0
end

local function expandBoardCorners(tl, tr, bl, br, padX, padY)
    padX = tonumber(padX) or 0.0
    padY = tonumber(padY) or 0.0
    if padX == 0.0 and padY == 0.0 then
        return tl, tr, bl, br
    end

    local right = tr - tl
    local up = tl - bl
    local rightLength = #right
    local upLength = #up
    if rightLength <= 0.001 or upLength <= 0.001 then
        return tl, tr, bl, br
    end

    local rightUnit = vector3(right.x / rightLength, right.y / rightLength, right.z / rightLength)
    local upUnit = vector3(up.x / upLength, up.y / upLength, up.z / upLength)

    return
        tl - (rightUnit * padX) + (upUnit * padY),
        tr + (rightUnit * padX) + (upUnit * padY),
        bl - (rightUnit * padX) - (upUnit * padY),
        br + (rightUnit * padX) - (upUnit * padY)
end

local function drawSolidBoardPlate(tl, tr, bl, br, side, color)
    color = color or { 0, 0, 0, 255 }
    local r = tonumber(color[1]) or 0
    local g = tonumber(color[2]) or 0
    local b = tonumber(color[3]) or 0
    local a = tonumber(color[4]) or 255

    if (tonumber(side) or 1.0) < 0.0 then
        DrawPoly(tl.x, tl.y, tl.z, bl.x, bl.y, bl.z, tr.x, tr.y, tr.z, r, g, b, a)
        DrawPoly(tr.x, tr.y, tr.z, bl.x, bl.y, bl.z, br.x, br.y, br.z, r, g, b, a)
        return
    end

    DrawPoly(tl.x, tl.y, tl.z, tr.x, tr.y, tr.z, bl.x, bl.y, bl.z, r, g, b, a)
    DrawPoly(tr.x, tr.y, tr.z, br.x, br.y, br.z, bl.x, bl.y, bl.z, r, g, b, a)
end

local function drawBoardBackplate(tl, tr, bl, br, side)
    local backplate = scoreboardConfig.Backplate or {}
    if backplate.Enabled == false then return end

    local plateTl, plateTr, plateBl, plateBr = expandBoardCorners(
        tl,
        tr,
        bl,
        br,
        backplate.PaddingX or 0.10,
        backplate.PaddingY or 0.10
    )

    drawSolidBoardPlate(plateTl, plateTr, plateBl, plateBr, side, backplate.Color)
end

local function drawBoardSurface(board, side)
    local tl, tr, bl, br = getBoardCorners(board, side)
    if not tl then return end

    drawBoardBackplate(tl, tr, bl, br, side)

    local uLeft, uRight = getBoardUv(board)
    if (tonumber(side) or 1.0) < 0.0 then
        -- Reverse winding on the rear model face so the DUI is rendered outward
        -- instead of being culled/hidden behind the prop surface.
        DrawSpritePoly(
            tl.x, tl.y, tl.z, bl.x, bl.y, bl.z, tr.x, tr.y, tr.z,
            255, 255, 255, 255,
            Scoreboard.txdName, Scoreboard.txnName,
            uLeft, 0.0, 1.0, uLeft, 1.0, 1.0, uRight, 0.0, 1.0
        )
        DrawSpritePoly(
            tr.x, tr.y, tr.z, bl.x, bl.y, bl.z, br.x, br.y, br.z,
            255, 255, 255, 255,
            Scoreboard.txdName, Scoreboard.txnName,
            uRight, 0.0, 1.0, uLeft, 1.0, 1.0, uRight, 1.0, 1.0
        )
        return
    end

    DrawSpritePoly(
        tl.x, tl.y, tl.z, tr.x, tr.y, tr.z, bl.x, bl.y, bl.z,
        255, 255, 255, 255,
        Scoreboard.txdName, Scoreboard.txnName,
        uLeft, 0.0, 1.0, uRight, 0.0, 1.0, uLeft, 1.0, 1.0
    )
    DrawSpritePoly(
        tr.x, tr.y, tr.z, br.x, br.y, br.z, bl.x, bl.y, bl.z,
        255, 255, 255, 255,
        Scoreboard.txdName, Scoreboard.txnName,
        uRight, 0.0, 1.0, uRight, 1.0, 1.0, uLeft, 1.0, 1.0
    )
end

local function drawBoard(board)
    if board.renderTarget and board.entity and DoesEntityExist(board.entity) and board.modelHash then
        drawBoardViaRenderTarget(board)
        return
    end
    local side = tonumber(scoreboardConfig.DrawSide) or 1.0
    drawBoardSurface(board, side)
    if scoreboardConfig.DrawBackFace == true then
        drawBoardSurface(board, -side)
    end
end

local function setupBoards()
    Scoreboard.boards = {}
    local boards = scoreboardConfig.Boards or {}
    for index, board in ipairs(boards) do
        if board.coords then
            Scoreboard.boards[#Scoreboard.boards + 1] = {
                id = board.id or ("scoreboard_%d"):format(index),
                coords = board.coords,
                heading = board.heading or 0.0,
                width = board.width or 3.7,
                height = board.height or 2.1,
                model = board.model,
                renderTarget = board.renderTarget,
                modelOffset = board.modelOffset,
                supportModel = board.supportModel,
                supportCoords = board.supportCoords,
                supportHeading = board.supportHeading,
                supportOffset = board.supportOffset,
                screenAnchorOffset = board.screenAnchorOffset,
                surfaceOffset = board.surfaceOffset,
                surfacePush = board.surfacePush,
                polyExtraForward = board.polyExtraForward,
                flipX = board.flipX,
                screenWidth = board.screenWidth,
                screenHeight = board.screenHeight,
                screenXOffset = board.screenXOffset,
                screenYOffset = board.screenYOffset,
                screenDepthOffset = board.screenDepthOffset,
                screenAxis = board.screenAxis,
                screenZOffset = board.screenZOffset,
                screenRotation = board.screenRotation,
            }
        end
    end
end

local function startRenderThreads()
