local function upsertDebugBoardAtPlayer(width, height)
    local ped = PlayerPedId()
    local coords = GetEntityCoords(ped)
    local heading = GetEntityHeading(ped)
    local forward = GetEntityForwardVector(ped)
    local boardCoords = coords + (forward * 5.0) + vector3(0.0, 0.0, 1.6)

    for index = #Scoreboard.boards, 1, -1 do
        local board = Scoreboard.boards[index]
        if board.id == "__dui_debug" then
            deleteBoardObject(board)
            table.remove(Scoreboard.boards, index)
        end
    end

    Scoreboard.boards[#Scoreboard.boards + 1] = {
        id = "__dui_debug",
        coords = boardCoords,
        heading = heading + 180.0,
        width = tonumber(width) or 3.6,
        height = tonumber(height) or 2.05,
        model = false,
        surfaceOffset = 0.0,
    }

    print(("[seoul_soccer] DUI debug board spawned at vector3(%.4f, %.4f, %.4f), heading %.2f"):format(boardCoords.x, boardCoords.y, boardCoords.z, heading + 180.0))
end
local function addTemporaryBoardAtPlayer(width, height)
    local ped = PlayerPedId()
    local coords = GetEntityCoords(ped)
    local heading = GetEntityHeading(ped)
    local forward = GetEntityForwardVector(ped)
    local boardCoords = coords + (forward * 5.0) + vector3(0.0, 0.0, 1.6)

    local board = {
        id = ("runtime_%d"):format(GetGameTimer()),
        coords = boardCoords,
        heading = heading + 180.0,
        width = tonumber(width) or 3.6,
        height = tonumber(height) or 2.05,
        model = false,
        surfaceOffset = 0.0,
    }

    Scoreboard.boards[#Scoreboard.boards + 1] = board
    Scoreboard.uiDirty = true
    local pcoords = GetEntityCoords(PlayerPedId())
    tryFlushDui(pcoords, tonumber(scoreboardConfig.DrawDistance) or 130.0)
    TriggerEvent("chat:addMessage", {
