local function recreateDui(mode)
    removeNativeScreenBind()
    if Scoreboard.dui then
        DestroyDui(Scoreboard.dui)
        Scoreboard.dui = nil
    end

    Scoreboard.imageTestMode = false
    Scoreboard.debugUrlMode = nil
    Scoreboard.txd = nil
    Scoreboard.texture = nil
    Scoreboard.lastMessage = ""
    Scoreboard.lastDuiVisualHash = nil
    Scoreboard.uiDirty = true

    if mode == "data" or mode == "cfx" then
        Scoreboard.debugUrlMode = mode
    elseif mode == "image" then
        Scoreboard.imageTestMode = true
        Scoreboard.txd = CreateRuntimeTxd(Scoreboard.txdName)
        Scoreboard.texture = CreateRuntimeTextureFromImage(Scoreboard.txd, Scoreboard.txnName, "web/dist/dui_probe.png")
        print(("[seoul_soccer] Stadium image test texture created: txd=%s txn=%s texture=%s"):format(Scoreboard.txdName, Scoreboard.txnName, tostring(Scoreboard.texture)))
    end

    upsertDebugBoardAtPlayer()
    local coords = GetEntityCoords(PlayerPedId())
    tryFlushDui(coords, tonumber(scoreboardConfig.DrawDistance) or 130.0)
end

if Config.Debug == true then
RegisterCommand("football_dui_test", function(_, args)
    local mode = tostring(args[1] or "data"):lower()
    if mode ~= "data" and mode ~= "nui" and mode ~= "cfx" and mode ~= "image" and mode ~= "reset" then
        TriggerEvent("chat:addMessage", { args = { "Football DUI", "Usage: /football_dui_test image|data|nui|cfx|reset" } })
        return
    end
    recreateDui(mode)
    print(("[seoul_soccer] DUI test command executed: %s"):format(mode))
    TriggerEvent("chat:addMessage", { args = { "Football DUI", ("DUI test mode: %s"):format(mode) } })
end, false)

RegisterCommand("football_screen_here", function(_, args)
    addTemporaryBoardAtPlayer(args[1], args[2])
end, false)

end

RegisterNetEvent("football:scoreboardStandby", function()
    Scoreboard.screenOff = true
    Scoreboard.pendingGoalPayload = nil
    Scoreboard.lastDuiVisualHash = nil
    Scoreboard.uiDirty = true
    local ped = PlayerPedId()
    local coords = GetEntityCoords(ped)
    local drawDistance = tonumber(scoreboardConfig.DrawDistance) or 130.0
    tryFlushDui(coords, drawDistance)
end)

RegisterNetEvent("football:syncState", function(payload)
    applyPayload(payload or {}, "update")
end)

RegisterNetEvent("football:startMatch", function(payload)
    payload = payload or {}
    payload.active = true
    applyPayload(payload, "update")
end)

RegisterNetEvent("football:updateScore", function(payload)
    applyPayload(payload or {}, "update")
end)

RegisterNetEvent("football:updateTime", function(payload)
    applyPayload(payload or {}, "update")
end)

RegisterNetEvent("football:goalScored", function(payload)
    applyPayload(payload or {}, "goal")
end)

RegisterNetEvent("football:endMatch", function(payload)
    payload = payload or {}
    payload.state = "ended"
    payload.status = payload.status or "FULL TIME"
    payload.active = true
    applyPayload(payload, "update")
end)

AddEventHandler("onClientResourceStart", function(startedResource)
    if startedResource ~= resourceName then return end
    if scoreboardConfig.Enabled == false then return end

    cleanupExistingBoardProps()
    stripScoreboardReplaceTextures()
    if Scoreboard.dui then
        DestroyDui(Scoreboard.dui)
        Scoreboard.dui = nil
    end

    setupBoards()
    Scoreboard.screenOff = true
    Scoreboard.state = {}
    Scoreboard.lastMessage = ""
    Scoreboard.lastDuiVisualHash = nil
    Scoreboard.pendingGoalPayload = nil
    Scoreboard.uiDirty = true
    TriggerServerEvent("football:requestSync")
    startRenderThreads()
end)

AddEventHandler("onClientResourceStop", function(stoppedResource)
    if stoppedResource ~= resourceName then return end

    for _, board in ipairs(Scoreboard.boards) do
        deleteBoardObject(board)
    end

    cleanupExistingBoardProps()
    stripScoreboardReplaceTextures()

    if Scoreboard.dui then
        DestroyDui(Scoreboard.dui)
        Scoreboard.dui = nil
    end

    Scoreboard.lastMessage = ""
    Scoreboard.lastDuiVisualHash = nil
    Scoreboard.state = {}
    Scoreboard.screenOff = true
    Scoreboard.pendingGoalPayload = nil
end)
